H.background();
const w = H.W, h = H.H;
const k = Math.max(0.1, P.k), A = P.A;
const omega = 2; // fixed visual rate; energy split is what matters
const x = A * Math.cos(omega * t);
const vel = -A * omega * Math.sin(omega * t);
const PE = 0.5 * k * x * x;
const KE = 0.5 * k * (A * A - x * x); // since (1/2)m v^2 with m chosen so total = (1/2)kA^2
const E = 0.5 * k * A * A;
// Top: potential well U(x) = 1/2 k x^2 with the ball rolling in it
const v = H.plot2d({ xMin: -Math.abs(A) - 0.5, xMax: Math.abs(A) + 0.5, yMin: -0.1 * E - 0.2, yMax: 1.25 * E + 0.3, box: { x: 60, y: 70, w: w * 0.56, h: h - 130 } });
v.grid(); v.axes();
v.fn(xx => 0.5 * k * xx * xx, { color: H.colors.violet, width: 3 });
v.line(-Math.abs(A) - 0.5, E, Math.abs(A) + 0.5, E, { color: H.colors.good, width: 1.5, dash: [5, 5] });
v.text("E (total)", Math.abs(A) - 0.3, E + 0.15 * E + 0.1, { color: H.colors.good, size: 12 });
v.dot(x, 0.5 * k * x * x, { r: 7, fill: H.colors.warn });
v.text("U(x)", -Math.abs(A) + 0.1, 1.05 * E, { color: H.colors.violet, size: 13 });
// Right: energy bars KE + PE = E
const bx = w * 0.74, bw = 60, baseY = h - 70, barH = h - 180;
const peFrac = E > 1e-9 ? PE / E : 0, keFrac = E > 1e-9 ? KE / E : 0;
H.rect(bx, baseY - barH * peFrac, bw, barH * peFrac, { fill: H.colors.violet });
H.rect(bx + bw + 20, baseY - barH * keFrac, bw, barH * keFrac, { fill: H.colors.accent });
H.line(bx - 10, baseY - barH, bx + 2 * bw + 30, baseY - barH, { color: H.colors.good, width: 1.5, dash: [4, 4] });
H.text("PE", bx + bw / 2 - 10, baseY + 18, { color: H.colors.violet, size: 13 });
H.text("KE", bx + bw + 20 + bw / 2 - 10, baseY + 18, { color: H.colors.accent, size: 13 });
H.text("= E", bx + 2 * bw + 36, baseY - barH - 4, { color: H.colors.good, size: 12 });
H.text("Energy in SHM:  E = KE + PE = (1/2)·k·A^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("x = " + x.toFixed(2) + " m   PE = " + PE.toFixed(2) + " J   KE = " + KE.toFixed(2) + " J   E = " + E.toFixed(2) + " J", 24, 52, { color: H.colors.sub, size: 13 });
